const MANIFEST = {
  "type": "Productivity.PomodoroTimer",
  "description": "Professional Pomodoro timer for productivity with work/break sessions, circular progress visualization, and session tracking. Ideal for time management and focused work periods.",
  "editorElement": {
    "selector": ".pomodoro-timer",
    "displayName": "Pomodoro Timer",
    "archetype": "container",
    "data": {
      "workDuration": {
        "dataType": "number",
        "displayName": "Work Duration (minutes)",
        "defaultValue": 25,
        "group": "Content"
      },
      "breakDuration": {
        "dataType": "number",
        "displayName": "Break Duration (minutes)",
        "defaultValue": 5,
        "group": "Content"
      },
      "longBreakDuration": {
        "dataType": "number",
        "displayName": "Long Break Duration (minutes)",
        "defaultValue": 15,
        "group": "Content"
      },
      "sessionsUntilLongBreak": {
        "dataType": "number",
        "displayName": "Sessions Until Long Break",
        "defaultValue": 4,
        "group": "Content"
      },
      "showSessionCounter": {
        "dataType": "booleanValue",
        "displayName": "Show Session Counter",
        "defaultValue": true,
        "group": "Content"
      },
      "autoStartBreaks": {
        "dataType": "booleanValue",
        "displayName": "Auto-start Breaks",
        "defaultValue": false,
        "group": "Content"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FAFBFC",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#1F2937",
        "group": "Colors"
      },
      "workAccentColor": {
        "dataType": "color",
        "displayName": "Work Accent Color",
        "defaultValue": "#3B82F6",
        "group": "Colors"
      },
      "breakAccentColor": {
        "dataType": "color",
        "displayName": "Break Accent Color",
        "defaultValue": "#10B981",
        "group": "Colors"
      },
      "trackColor": {
        "dataType": "color",
        "displayName": "Progress Track Color",
        "defaultValue": "#E5E7EB",
        "group": "Colors"
      },
      "timerFontSize": {
        "dataType": "number",
        "displayName": "Timer Font Size (px)",
        "defaultValue": 64,
        "group": "Typography"
      },
      "labelFontSize": {
        "dataType": "number",
        "displayName": "Label Font Size (px)",
        "defaultValue": 14,
        "group": "Typography"
      },
      "circleSize": {
        "dataType": "number",
        "displayName": "Circle Size (px)",
        "defaultValue": 240,
        "group": "Layout"
      },
      "containerPadding": {
        "dataType": "number",
        "displayName": "Container Padding (px)",
        "defaultValue": 48,
        "group": "Layout"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const workDuration = parseInt(config?.workDuration || "25");
  const breakDuration = parseInt(config?.breakDuration || "5");
  const longBreakDuration = parseInt(config?.longBreakDuration || "15");
  const sessionsUntilLongBreak = parseInt(config?.sessionsUntilLongBreak || "4");
  const showSessionCounter = config?.showSessionCounter !== false;
  const autoStartBreaks = config?.autoStartBreaks === true;
  const backgroundColor = config?.backgroundColor || "#FAFBFC";
  const textColor = config?.textColor || "#1F2937";
  const workAccentColor = config?.workAccentColor || "#3B82F6";
  const breakAccentColor = config?.breakAccentColor || "#10B981";
  const trackColor = config?.trackColor || "#E5E7EB";
  const timerFontSize = parseInt(config?.timerFontSize || "64");
  const labelFontSize = parseInt(config?.labelFontSize || "14");
  const circleSize = parseInt(config?.circleSize || "240");
  const containerPadding = parseInt(config?.containerPadding || "48");

  const [timeLeft, setTimeLeft] = React.useState(workDuration * 60);
  const [isRunning, setIsRunning] = React.useState(false);
  const [mode, setMode] = React.useState('work'); // 'work', 'break', 'longBreak'
  const [sessionsCompleted, setSessionsCompleted] = React.useState(0);
  const intervalRef = React.useRef(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const totalTime = mode === 'work' ? workDuration * 60 : 
                    mode === 'break' ? breakDuration * 60 : 
                    longBreakDuration * 60;

  const progress = ((totalTime - timeLeft) / totalTime) * 100;
  const currentAccent = mode === 'work' ? workAccentColor : breakAccentColor;

  React.useEffect(() => {
    if (isRunning && timeLeft > 0) {
      intervalRef.current = setInterval(() => {
        setTimeLeft(prev => {
          if (prev <= 1) {
            handleTimerComplete();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } else {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    }

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [isRunning, timeLeft]);

  const handleTimerComplete = () => {
    setIsRunning(false);

    if (mode === 'work') {
      const newSessionCount = sessionsCompleted + 1;
      setSessionsCompleted(newSessionCount);

      if (newSessionCount % sessionsUntilLongBreak === 0) {
        setMode('longBreak');
        setTimeLeft(longBreakDuration * 60);
      } else {
        setMode('break');
        setTimeLeft(breakDuration * 60);
      }

      if (autoStartBreaks) {
        setIsRunning(true);
      }
    } else {
      setMode('work');
      setTimeLeft(workDuration * 60);
    }
  };

  const toggleTimer = () => {
    setIsRunning(!isRunning);
  };

  const resetTimer = () => {
    setIsRunning(false);
    if (mode === 'work') {
      setTimeLeft(workDuration * 60);
    } else if (mode === 'break') {
      setTimeLeft(breakDuration * 60);
    } else {
      setTimeLeft(longBreakDuration * 60);
    }
  };

  const skipSession = () => {
    setIsRunning(false);
    if (mode === 'work') {
      setMode('break');
      setTimeLeft(breakDuration * 60);
    } else {
      setMode('work');
      setTimeLeft(workDuration * 60);
    }
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const circumference = 2 * Math.PI * (circleSize / 2 - 10);
  const strokeDashoffset = circumference - (progress / 100) * circumference;

  return (
    <div 
      className="pomodoro-timer"
      style={{
        width: '100%',
        minHeight: '500px',
        padding: `${containerPadding}px`,
        backgroundColor: backgroundColor,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        gap: '24px',
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
        transition: prefersReducedMotion ? 'none' : 'background-color 400ms ease-out'
      }}
    >
      {/* Session Counter */}
      {showSessionCounter && (
        <div style={{
          fontSize: `${labelFontSize}px`,
          fontWeight: '500',
          color: '#6B7280',
          letterSpacing: '0.025em',
          textTransform: 'uppercase',
          opacity: 0,
          animation: prefersReducedMotion ? 'none' : 'fadeIn 400ms ease-out forwards'
        }}>
          Session {sessionsCompleted + 1}
        </div>
      )}

      {/* Circular Progress Timer */}
      <div style={{
        position: 'relative',
        width: `${circleSize}px`,
        height: `${circleSize}px`,
        opacity: 0,
        animation: prefersReducedMotion ? 'none' : 'fadeIn 400ms ease-out 100ms forwards'
      }}>
        <svg width={circleSize} height={circleSize} style={{ transform: 'rotate(-90deg)' }}>
          {/* Background track */}
          <circle
            cx={circleSize / 2}
            cy={circleSize / 2}
            r={circleSize / 2 - 10}
            fill="none"
            stroke={trackColor}
            strokeWidth="8"
          />
          {/* Progress arc */}
          <circle
            cx={circleSize / 2}
            cy={circleSize / 2}
            r={circleSize / 2 - 10}
            fill="none"
            stroke={currentAccent}
            strokeWidth="8"
            strokeLinecap="round"
            strokeDasharray={circumference}
            strokeDashoffset={strokeDashoffset}
            style={{
              transition: prefersReducedMotion ? 'none' : 'stroke-dashoffset 1s ease-out, stroke 400ms ease-out'
            }}
          />
        </svg>

        {/* Timer Display */}
        <div style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          textAlign: 'center'
        }}>
          <div style={{
            fontSize: `clamp(${timerFontSize * 0.5}px, ${timerFontSize * 0.1}vw, ${timerFontSize}px)`,
            fontWeight: '300',
            color: textColor,
            lineHeight: '1',
            marginBottom: '8px',
            transition: prefersReducedMotion ? 'none' : 'opacity 150ms ease-out'
          }}>
            {formatTime(timeLeft)}
          </div>
          <div style={{
            fontSize: `${labelFontSize}px`,
            fontWeight: '500',
            color: currentAccent,
            letterSpacing: '0.025em',
            textTransform: 'uppercase',
            transition: prefersReducedMotion ? 'none' : 'color 400ms ease-out'
          }}>
            {mode === 'work' ? 'Focus' : mode === 'break' ? 'Break' : 'Long Break'}
          </div>
        </div>
      </div>

      {/* Controls */}
      <div style={{
        display: 'flex',
        gap: '12px',
        flexWrap: 'wrap',
        justifyContent: 'center',
        opacity: 0,
        animation: prefersReducedMotion ? 'none' : 'fadeIn 400ms ease-out 200ms forwards'
      }}>
        <button
          onClick={toggleTimer}
          style={{
            padding: '12px 32px',
            fontSize: '16px',
            fontWeight: '500',
            color: '#FFFFFF',
            backgroundColor: currentAccent,
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out',
            boxShadow: `0 4px 12px ${currentAccent}40`
          }}
          onMouseEnter={(e) => {
            if (!prefersReducedMotion) {
              e.currentTarget.style.transform = 'scale(1.02)';
              e.currentTarget.style.boxShadow = `0 6px 16px ${currentAccent}50`;
            }
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.transform = 'scale(1)';
            e.currentTarget.style.boxShadow = `0 4px 12px ${currentAccent}40`;
          }}
          onMouseDown={(e) => {
            if (!prefersReducedMotion) {
              e.currentTarget.style.transform = 'scale(0.98)';
            }
          }}
          onMouseUp={(e) => {
            if (!prefersReducedMotion) {
              e.currentTarget.style.transform = 'scale(1.02)';
            }
          }}
        >
          {isRunning ? 'Pause' : 'Start'}
        </button>

        <button
          onClick={resetTimer}
          style={{
            padding: '12px 24px',
            fontSize: '16px',
            fontWeight: '500',
            color: textColor,
            backgroundColor: 'transparent',
            border: `1px solid #E5E7EB`,
            borderRadius: '6px',
            cursor: 'pointer',
            transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = '#E5E7EB';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = 'transparent';
          }}
        >
          Reset
        </button>

        <button
          onClick={skipSession}
          style={{
            padding: '12px 24px',
            fontSize: '16px',
            fontWeight: '500',
            color: textColor,
            backgroundColor: 'transparent',
            border: `1px solid #E5E7EB`,
            borderRadius: '6px',
            cursor: 'pointer',
            transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = '#E5E7EB';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = 'transparent';
          }}
        >
          Skip
        </button>
      </div>

      <style>{`
        @keyframes fadeIn {
          from {
            opacity: 0;
            transform: translateY(10px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }

        .pomodoro-timer button:focus-visible {
          outline: 2px solid ${currentAccent};
          outline-offset: 2px;
        }
      `}</style>
    </div>
  );
}

