};

function Component({ config = {} }) {
  // Safe config access with defaults
  const canvasBackground = config?.canvasBackground || "dark";
  const autoDrawOnMove = config?.autoDrawOnMove !== false;
  const brushPreset = config?.brushPreset || "smooth";
  const strokeWidth = parseInt(config?.strokeWidth || "30");
  const strokeOpacity = parseFloat(config?.strokeOpacity || "0.6");
  const smoothing = parseFloat(config?.smoothing || "0.3");
  const colorShiftSpeed = parseFloat(config?.colorShiftSpeed || "1.0");
  const saturation = parseInt(config?.saturation || "80");
  const lightness = parseInt(config?.lightness || "50");
  const cursorStyle = config?.cursorStyle || "magnetic-glow";
  const cursorSize = parseInt(config?.cursorSize || "40");
  const enableMagnetic = config?.enableMagnetic !== false;
  const magneticStrength = parseFloat(config?.magneticStrength || "0.25");
  const cursorColor = config?.cursorColor || "#FFFFFF";
  const cursorAccentColor = config?.cursorAccentColor || "#6C757D";
  const canvasWidth = config?.canvasWidth || "100%";
  const canvasHeight = parseInt(config?.canvasHeight || "600");
  const cornerRadius = config?.cornerRadius || "8";

  const canvasRef = useRef(null);
  const containerRef = useRef(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [cursorPos, setCursorPos] = useState({ x: -100, y: -100 });
  const [particles, setParticles] = useState([]);
  const lastPoint = useRef(null);
  const hueRef = useRef(0);
  const animationFrameRef = useRef(null);
  const particlesRef = useRef([]);

  const bgColor = canvasBackground === "dark" ? "#212529" : "#FFFFFF";

  // Color animation loop
  useEffect(() => {
    const animate = () => {
      hueRef.current = (hueRef.current + colorShiftSpeed * 0.5) % 360;
      animationFrameRef.current = requestAnimationFrame(animate);
    };
    animate();

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, [colorShiftSpeed]);

  const getCurrentColor = () => {
    return `hsl(${hueRef.current}, ${saturation}%, ${lightness}%)`;
  };

  // ZERO LATENCY cursor tracking with magnetic effect
  useEffect(() => {
    const handleMouseMove = (e) => {
      if (!containerRef.current) {
        setCursorPos({ x: e.clientX, y: e.clientY });
        return;
      }

      let targetX = e.clientX;
      let targetY = e.clientY;

      // Magnetic attraction to canvas edges and corners
      if (enableMagnetic) {
        const rect = containerRef.current.getBoundingClientRect();
        const corners = [
          { x: rect.left, y: rect.top },
          { x: rect.right, y: rect.top },
          { x: rect.left, y: rect.bottom },
          { x: rect.right, y: rect.bottom }
        ];

        corners.forEach(corner => {
          const distance = Math.hypot(targetX - corner.x, targetY - corner.y);
          const magneticRadius = 80;

          if (distance < magneticRadius) {
            const force = (1 - distance / magneticRadius) * magneticStrength;
            targetX += (corner.x - targetX) * force;
            targetY += (corner.y - targetY) * force;
          }
        });

        // Edge attraction
        const edgeMargin = 60;
        if (targetX > rect.left - edgeMargin && targetX < rect.left + edgeMargin) {
          const force = (1 - Math.abs(targetX - rect.left) / edgeMargin) * magneticStrength * 0.5;
          targetX += (rect.left - targetX) * force;
        }
        if (targetX > rect.right - edgeMargin && targetX < rect.right + edgeMargin) {
          const force = (1 - Math.abs(targetX - rect.right) / edgeMargin) * magneticStrength * 0.5;
          targetX += (rect.right - targetX) * force;
        }
      }

      // INSTANT UPDATE - NO INTERPOLATION
      setCursorPos({ x: targetX, y: targetY });

      // Particle trail during drawing
      if ((cursorStyle === 'particle-trail' || cursorStyle === 'dynamic-color') && (isDrawing || autoDrawOnMove)) {
        const newParticle = {
          id: Date.now() + Math.random(),
          x: targetX,
          y: targetY,
          hue: hueRef.current,
          life: 1.0
        };
        setParticles(prev => [...prev.slice(-30), newParticle]);
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [enableMagnetic, magneticStrength, cursorStyle, isDrawing, autoDrawOnMove]);

  // Particle decay
  useEffect(() => {
    if (cursorStyle !== 'particle-trail' && cursorStyle !== 'dynamic-color') return;

    const interval = setInterval(() => {
      setParticles(prev => 
        prev
          .map(p => ({ ...p, life: p.life - 0.08 }))
          .filter(p => p.life > 0)
      );
    }, 50);

    return () => clearInterval(interval);
  }, [cursorStyle]);

  const drawSmooth = (ctx, x, y, lastX, lastY) => {
    ctx.strokeStyle = getCurrentColor();
    ctx.lineWidth = strokeWidth;
    ctx.globalAlpha = strokeOpacity;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    if (smoothing > 0 && lastX !== null) {
      const smoothX = lastX + (x - lastX) * (1 - smoothing);
      const smoothY = lastY + (y - lastY) * (1 - smoothing);

      ctx.beginPath();
      ctx.moveTo(lastX, lastY);
      ctx.lineTo(smoothX, smoothY);
      ctx.stroke();

      return { x: smoothX, y: smoothY };
    } else {
      ctx.beginPath();
      ctx.moveTo(lastX || x, lastY || y);
      ctx.lineTo(x, y);
      ctx.stroke();

      return { x, y };
    }
  };

  const drawSpray = (ctx, x, y) => {
    const density = strokeWidth * 0.3;
    ctx.globalAlpha = strokeOpacity * 0.5;

    for (let i = 0; i < density; i++) {
      const angle = Math.random() * Math.PI * 2;
      const radius = Math.random() * strokeWidth;
      const offsetX = Math.cos(angle) * radius;
      const offsetY = Math.sin(angle) * radius;

      ctx.fillStyle = getCurrentColor();
      ctx.beginPath();
      ctx.arc(x + offsetX, y + offsetY, Math.random() * 2 + 1, 0, Math.PI * 2);
      ctx.fill();
    }
  };

  const drawGlow = (ctx, x, y, lastX, lastY) => {
    const layers = 5;

    for (let i = layers; i > 0; i--) {
      ctx.strokeStyle = getCurrentColor();
      ctx.lineWidth = strokeWidth * (i / layers);
      ctx.globalAlpha = strokeOpacity * (1 / (i * 2));
      ctx.lineCap = 'round';

      ctx.beginPath();
      ctx.moveTo(lastX || x, lastY || y);
      ctx.lineTo(x, y);
      ctx.stroke();
    }
  };

  const drawRibbon = (ctx, x, y, lastX, lastY) => {
    if (lastX === null || lastY === null) return { x, y };

    const dx = x - lastX;
    const dy = y - lastY;
    const angle = Math.atan2(dy, dx);
    const perpAngle = angle + Math.PI / 2;

    const ribbonWidth = strokeWidth;

    ctx.globalAlpha = strokeOpacity;
    ctx.fillStyle = getCurrentColor();

    ctx.beginPath();
    ctx.moveTo(
      lastX + Math.cos(perpAngle) * ribbonWidth / 2,
      lastY + Math.sin(perpAngle) * ribbonWidth / 2
    );
    ctx.lineTo(
      x + Math.cos(perpAngle) * ribbonWidth / 2,
      y + Math.sin(perpAngle) * ribbonWidth / 2
    );
    ctx.lineTo(
      x - Math.cos(perpAngle) * ribbonWidth / 2,
      y - Math.sin(perpAngle) * ribbonWidth / 2
    );
    ctx.lineTo(
      lastX - Math.cos(perpAngle) * ribbonWidth / 2,
      lastY - Math.sin(perpAngle) * ribbonWidth / 2
    );
    ctx.closePath();
    ctx.fill();

    return { x, y };
  };

  const drawConstellation = (ctx, x, y) => {
    particlesRef.current.push({
      x,
      y,
      hue: hueRef.current,
      life: 1.0
    });

    particlesRef.current = particlesRef.current.slice(-50);

    ctx.globalAlpha = strokeOpacity * 0.3;
    particlesRef.current.forEach((particle, i) => {
      if (particle.life <= 0) return;

      ctx.fillStyle = `hsl(${particle.hue}, ${saturation}%, ${lightness}%)`;
      ctx.globalAlpha = strokeOpacity * particle.life;
      ctx.beginPath();
      ctx.arc(particle.x, particle.y, 3, 0, Math.PI * 2);
      ctx.fill();

      particlesRef.current.slice(i + 1).forEach(other => {
        const dist = Math.hypot(other.x - particle.x, other.y - particle.y);
        if (dist < strokeWidth * 2) {
          ctx.strokeStyle = `hsl(${particle.hue}, ${saturation}%, ${lightness}%)`;
          ctx.globalAlpha = strokeOpacity * particle.life * (1 - dist / (strokeWidth * 2));
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(particle.x, particle.y);
          ctx.lineTo(other.x, other.y);
          ctx.stroke();
        }
      });

      particle.life -= 0.02;
    });

    particlesRef.current = particlesRef.current.filter(p => p.life > 0);
  };

  const drawWeb = (ctx, x, y) => {
    particlesRef.current.push({
      x,
      y,
      hue: hueRef.current,
      life: 1.0
    });

    particlesRef.current = particlesRef.current.slice(-30);

    particlesRef.current.forEach((particle, i) => {
      if (particle.life <= 0) return;

      particlesRef.current.slice(i + 1).forEach(other => {
        const dist = Math.hypot(other.x - particle.x, other.y - particle.y);
        if (dist < strokeWidth * 3) {
          ctx.strokeStyle = `hsl(${(particle.hue + other.hue) / 2}, ${saturation}%, ${lightness}%)`;
          ctx.globalAlpha = strokeOpacity * particle.life * other.life * (1 - dist / (strokeWidth * 3));
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.moveTo(particle.x, particle.y);
          ctx.lineTo(other.x, other.y);
          ctx.stroke();
        }
      });

      particle.life -= 0.015;
    });

    particlesRef.current = particlesRef.current.filter(p => p.life > 0);
  };

  const draw = (e) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    if (!autoDrawOnMove && !isDrawing) return;

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const ctx = canvas.getContext('2d');

    const lastX = lastPoint.current?.x || null;
    const lastY = lastPoint.current?.y || null;

    switch (brushPreset) {
      case 'smooth':
        lastPoint.current = drawSmooth(ctx, x, y, lastX, lastY);
        break;
      case 'spray':
        drawSpray(ctx, x, y);
        lastPoint.current = { x, y };
        break;
      case 'glow':
        drawGlow(ctx, x, y, lastX, lastY);
        lastPoint.current = { x, y };
        break;
      case 'ribbon':
        lastPoint.current = drawRibbon(ctx, x, y, lastX, lastY);
        break;
      case 'constellation':
        drawConstellation(ctx, x, y);
        lastPoint.current = { x, y };
        break;
      case 'web':
        drawWeb(ctx, x, y);
        lastPoint.current = { x, y };
        break;
      default:
        lastPoint.current = drawSmooth(ctx, x, y, lastX, lastY);
    }
  };

  const handleMouseDown = (e) => {
    setIsDrawing(true);
    if (!autoDrawOnMove) {
      draw(e);
    }
  };

  const handleMouseMove = (e) => {
    draw(e);
  };

  const handleMouseUp = () => {
    setIsDrawing(false);
    lastPoint.current = null;
  };

  const clearCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    particlesRef.current = [];
  };

  useEffect(() => {
    const handleKeyPress = (e) => {
      if (e.key === 'c' || e.key === 'C') {
        clearCanvas();
      }
    };

    window.addEventListener('keydown', handleKeyPress);
    return () => window.removeEventListener('keydown', handleKeyPress);
  }, []);

  const getCursorStyles = () => {
    const baseSize = cursorSize;
    const scale = isDrawing || (autoDrawOnMove && cursorPos.x > 0) ? 1.3 : 1;
    const currentHue = hueRef.current;
    const dynamicColor = `hsl(${currentHue}, ${saturation}%, ${lightness}%)`;

    const styles = {
      position: 'fixed',
      left: cursorPos.x - baseSize / 2,
      top: cursorPos.y - baseSize / 2,
      width: `${baseSize}px`,
      height: `${baseSize}px`,
      transform: `scale(${scale})`,
      pointerEvents: 'none',
      zIndex: 10000,
      transition: 'transform 0.3s ease-out',
      borderRadius: '50%'
    };

    switch (cursorStyle) {
      case 'magnetic-glow':
        return {
          ...styles,
          background: `radial-gradient(circle, ${cursorColor}60 0%, ${cursorColor}30 50%, transparent 70%)`,
          border: `2px solid ${cursorColor}`,
          boxShadow: isDrawing ? `0 0 40px ${cursorAccentColor}` : `0 0 20px ${cursorAccentColor}40`,
          backdropFilter: 'blur(3px)'
        };

      case 'dynamic-color':
        return {
          ...styles,
          background: `radial-gradient(circle, ${dynamicColor}80 0%, ${dynamicColor}40 50%, transparent 70%)`,
          border: `3px solid ${dynamicColor}`,
          boxShadow: `0 0 30px ${dynamicColor}80`,
          backdropFilter: 'blur(2px)'
        };

      case 'blend-mode':
        return {
          ...styles,
          background: cursorColor,
          mixBlendMode: 'difference'
        };

      case 'morphing-ring':
        return {
          ...styles,
          background: 'transparent',
          border: `3px solid ${cursorColor}`,
          boxShadow: `inset 0 0 0 ${isDrawing ? '20px' : '0px'} ${cursorAccentColor}60`
        };

      case 'minimal-dot':
        return {
          ...styles,
          width: `${baseSize / 3}px`,
          height: `${baseSize / 3}px`,
          left: cursorPos.x - baseSize / 6,
          top: cursorPos.y - baseSize / 6,
          background: cursorColor,
          boxShadow: `0 0 0 ${isDrawing ? '25px' : '15px'} ${cursorAccentColor}30`
        };

      default:
        return styles;
    }
  };

  return (
    <div 
      className="fluid-color-canvas-pro"
      ref={containerRef}
      style={{
        width: '100%',
        maxWidth: canvasWidth === '100%' ? '100%' : `${canvasWidth}px`,
        margin: '0 auto',
        position: 'relative',
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
        cursor: 'none'
      }}
    >
      {/* ZERO LATENCY Custom Cursor */}
      <div style={getCursorStyles()} />

      {/* Particle Trail */}
      {(cursorStyle === 'particle-trail' || cursorStyle === 'dynamic-color') && particles.map(particle => (
        <div
          key={particle.id}
          style={{
            position: 'fixed',
            left: particle.x - 5,
            top: particle.y - 5,
            width: '10px',
            height: '10px',
            borderRadius: '50%',
            background: cursorStyle === 'dynamic-color' 
              ? `hsl(${particle.hue}, ${saturation}%, ${lightness}%)`
              : cursorAccentColor,
            opacity: particle.life * 0.8,
            pointerEvents: 'none',
            zIndex: 9999,
            boxShadow: `0 0 10px ${cursorStyle === 'dynamic-color' 
              ? `hsl(${particle.hue}, ${saturation}%, ${lightness}%)`
              : cursorAccentColor}`
          }}
        />
      ))}

      <canvas
        ref={canvasRef}
        width={canvasWidth === '100%' ? 1400 : parseInt(canvasWidth)}
        height={canvasHeight}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        style={{
          backgroundColor: bgColor,
          borderRadius: `${cornerRadius}px`,
          cursor: 'none',
          display: 'block',
          width: '100%',
          height: 'auto',
          touchAction: 'none'
        }}
      />

      <div style={{
        position: 'absolute',
        bottom: '16px',
        left: '50%',
        transform: 'translateX(-50%)',
        backgroundColor: canvasBackground === 'dark' ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)',
        backdropFilter: 'blur(10px)',
        padding: '8px 16px',
        borderRadius: '20px',
        color: canvasBackground === 'dark' ? '#FFFFFF' : '#212529',
        fontSize: '12px',
        fontWeight: '400',
        pointerEvents: 'none',
        opacity: 0.7
      }}>
        Press 'C' to clear canvas
      </div>
    </div>
  );
}

