function Component({ config = {} }) {
  const [sections, setSections] = React.useState([]);
  const [selectedSection, setSelectedSection] = React.useState(null);
  const [expandedSubjects, setExpandedSubjects] = React.useState(new Set());
  const [searchQuery, setSearchQuery] = React.useState('');
  const [parseMode, setParseMode] = React.useState(false);
  const [rawPrompt, setRawPrompt] = React.useState('');
  const [activeTab, setActiveTab] = React.useState('edit');
  const [editingSubject, setEditingSubject] = React.useState(null);
  const contentRefs = React.useRef({});

  // Safe config access
  const backgroundColor = config?.backgroundColor || '#FFFFFF';
  const sidebarBg = config?.sidebarBackgroundColor || '#F8F9FA';
  const headerText = config?.headerTextColor || '#212529';
  const contentBg = config?.contentBackgroundColor || '#FFFFFF';
  const contentText = config?.contentTextColor || '#495057';
  const borderColor = config?.borderColor || '#E9ECEF';
  const accentColor = config?.accentColor || '#495057';
  const activeBg = config?.activeBackgroundColor || '#FFFFFF';
  const fontSize = config?.fontSize || 15;
  const fontFamily = config?.fontFamily || 'system-ui, -apple-system, sans-serif';
  const lineHeight = config?.lineHeight || '1.6';
  const showSearch = config?.showSearch !== false;
  const showActions = config?.showActions !== false;
  const showLivePreview = config?.showLivePreview !== false;
  const previewPosition = config?.previewPosition || 'bottom';

  // Check for reduced motion preference
  const prefersReducedMotion = typeof window !== 'undefined' 
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches 
    : false;

  // Parse prompt into sections
  const parsePrompt = (text) => {
    const lines = text.split('\n');
    const parsed = [];
    let currentH1 = null;
    let currentH2 = null;
    let currentH3 = null;
    let buffer = [];
    let inCodeBlock = false;
    let inXmlBlock = false;
    let xmlBlockName = '';

    const createSection = (level, title, content = '') => ({
      id: Date.now() + Math.random(),
      level,
      title: title.trim(),
      content: content.trim(),
      visible: true,
      subjects: []
    });

    const saveBuffer = () => {
      const content = buffer.join('\n').trim();
      if (currentH3) {
        currentH3.content = content;
      } else if (currentH2) {
        currentH2.content = content;
      } else if (currentH1) {
        currentH1.content = content;
      }
      buffer = [];
    };

    lines.forEach((line) => {
      if (line.trim().startsWith('```')) {
        inCodeBlock = !inCodeBlock;
        buffer.push(line);
        return;
      }

      if (inCodeBlock) {
        buffer.push(line);
        return;
      }

      const xmlOpenMatch = line.match(/^<([a-zA-Z_][a-zA-Z0-9_]*)>$/);
      if (xmlOpenMatch && !inXmlBlock) {
        saveBuffer();
        inXmlBlock = true;
        xmlBlockName = xmlOpenMatch[1];
        currentH2 = createSection(2, xmlBlockName);
        if (currentH1) {
          currentH1.subjects.push(currentH2);
        } else {
          parsed.push(currentH2);
        }
        currentH3 = null;
        return;
      }

      const xmlCloseMatch = line.match(/^<\/([a-zA-Z_][a-zA-Z0-9_]*)>$/);
      if (xmlCloseMatch && inXmlBlock && xmlCloseMatch[1] === xmlBlockName) {
        saveBuffer();
        inXmlBlock = false;
        xmlBlockName = '';
        return;
      }

      if (inXmlBlock) {
        buffer.push(line);
        return;
      }

      if (line.match(/^#\s+[^#]/)) {
        saveBuffer();
        const title = line.replace(/^#\s+/, '');
        currentH1 = createSection(1, title);
        parsed.push(currentH1);
        currentH2 = null;
        currentH3 = null;
      } else if (line.match(/^##\s+[^#]/)) {
        saveBuffer();
        const title = line.replace(/^##\s+/, '');
        currentH2 = createSection(2, title);
        if (currentH1) {
          currentH1.subjects.push(currentH2);
        } else {
          parsed.push(currentH2);
        }
        currentH3 = null;
      } else if (line.match(/^###\s+[^#]/)) {
        saveBuffer();
        const title = line.replace(/^###\s+/, '');
        currentH3 = createSection(3, title);
        if (currentH2) {
          currentH2.subjects.push(currentH3);
        } else if (currentH1) {
          currentH1.subjects.push(currentH3);
        } else {
          parsed.push(currentH3);
        }
      } else {
        buffer.push(line);
      }
    });

    saveBuffer();
    return parsed;
  };

  // Handle parsing
  const handleParse = () => {
    const parsed = parsePrompt(rawPrompt);
    setSections(parsed);
    if (parsed.length > 0) {
      setSelectedSection(parsed[0]);
    }
    setParseMode(true);
  };

  // Toggle subject expansion
  const toggleSubject = (id) => {
    setExpandedSubjects(prev => {
      const newSet = new Set(prev);
      if (newSet.has(id)) {
        newSet.delete(id);
      } else {
        newSet.add(id);
      }
      return newSet;
    });
  };

  const isSubjectExpanded = (id) => expandedSubjects.has(id);

  // Search filter
  const filterContent = (text) => {
    if (!searchQuery) return true;
    return text.toLowerCase().includes(searchQuery.toLowerCase());
  };

  // Highlight search text
  const highlightText = (text) => {
    if (!searchQuery) return text;
    const regex = new RegExp(`(${searchQuery})`, 'gi');
    return text.replace(regex, '<mark style="background-color: #FFF3CD; padding: 2px 4px; border-radius: 2px;">$1</mark>');
  };

  // Simple markdown renderer
  const renderMarkdown = (text) => {
    let html = text;

    // Code blocks
    html = html.replace(/```(\w+)?\n([\s\S]*?)```/g, (match, lang, code) => {
      return `<pre style="background-color: ${sidebarBg}; padding: 16px; border-radius: 4px; overflow-x: auto; font-family: monospace; font-size: ${fontSize * 0.9}px; margin: 16px 0;"><code>${code.trim()}</code></pre>`;
    });

    // Inline code
    html = html.replace(/`([^`]+)`/g, '<code style="background-color: ' + sidebarBg + '; padding: 2px 6px; border-radius: 3px; font-family: monospace; font-size: ' + (fontSize * 0.9) + 'px;">$1</code>');

    // Bold
    html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');

    // Headers
    html = html.replace(/^### (.+)$/gm, '<h4 style="font-size: ' + (fontSize * 1.2) + 'px; font-weight: 500; margin: 24px 0 12px 0; color: ' + headerText + ';">$1</h4>');
    html = html.replace(/^## (.+)$/gm, '<h3 style="font-size: ' + (fontSize * 1.4) + 'px; font-weight: 500; margin: 28px 0 14px 0; color: ' + headerText + ';">$1</h3>');
    html = html.replace(/^# (.+)$/gm, '<h2 style="font-size: ' + (fontSize * 1.6) + 'px; font-weight: 400; margin: 32px 0 16px 0; color: ' + headerText + ';">$1</h2>');

    // Line breaks
    html = html.replace(/\n\n/g, '<br/><br/>');

    // Highlight search
    if (searchQuery) {
      const regex = new RegExp(`(${searchQuery})`, 'gi');
      html = html.replace(regex, '<mark style="background-color: #FFF3CD; padding: 2px 4px; border-radius: 2px;">$1</mark>');
    }

    return html;
  };

  // Toggle visibility
  const toggleVisibility = (id) => {
    const updateSections = (sectionList) => {
      return sectionList.map(section => {
        if (section.id === id) {
          return { ...section, visible: !section.visible };
        }
        if (section.subjects) {
          return { ...section, subjects: updateSections(section.subjects) };
        }
        return section;
      });
    };
    setSections(updateSections(sections));
  };

  // Delete section
  const deleteSection = (id) => {
    const removeSections = (sectionList) => {
      return sectionList
        .filter(section => section.id !== id)
        .map(section => ({
          ...section,
          subjects: section.subjects ? removeSections(section.subjects) : []
        }));
    };
    setSections(removeSections(sections));
    if (selectedSection?.id === id) {
      setSelectedSection(sections[0]);
    }
  };

  // Move section
  const moveSection = (id, direction) => {
    const moveSections = (sectionList) => {
      const idx = sectionList.findIndex(s => s.id === id);
      if (idx === -1) {
        return sectionList.map(section => ({
          ...section,
          subjects: section.subjects ? moveSections(section.subjects) : []
        }));
      }

      if (direction === 'up' && idx > 0) {
        const newList = [...sectionList];
        [newList[idx - 1], newList[idx]] = [newList[idx], newList[idx - 1]];
        return newList;
      }

      if (direction === 'down' && idx < sectionList.length - 1) {
        const newList = [...sectionList];
        [newList[idx], newList[idx + 1]] = [newList[idx + 1], newList[idx]];
        return newList;
      }

      return sectionList;
    };

    setSections(moveSections(sections));
  };

  // Update section title
  const updateSectionTitle = (id, newTitle) => {
    const updateSections = (sectionList) => {
      return sectionList.map(section => {
        if (section.id === id) {
          const updated = { ...section, title: newTitle };
          if (selectedSection?.id === id) {
            setSelectedSection(updated);
          }
          return updated;
        }
        if (section.subjects) {
          return { ...section, subjects: updateSections(section.subjects) };
        }
        return section;
      });
    };
    setSections(updateSections(sections));
  };

  // Update subject content
  const updateSubjectContent = (sectionId, subjectId, newContent) => {
    const updateSections = (sectionList) => {
      return sectionList.map(section => {
        if (section.id === sectionId) {
          const updatedSubjects = section.subjects.map(subject => {
            if (subject.id === subjectId) {
              return { ...subject, content: newContent };
            }
            return subject;
          });
          const updated = { ...section, subjects: updatedSubjects };
          if (selectedSection?.id === sectionId) {
            setSelectedSection(updated);
          }
          return updated;
        }
        if (section.subjects) {
          return { ...section, subjects: updateSections(section.subjects) };
        }
        return section;
      });
    };
    setSections(updateSections(sections));
  };

  // Update subject title
  const updateSubjectTitle = (sectionId, subjectId, newTitle) => {
    const updateSections = (sectionList) => {
      return sectionList.map(section => {
        if (section.id === sectionId) {
          const updatedSubjects = section.subjects.map(subject => {
            if (subject.id === subjectId) {
              return { ...subject, title: newTitle };
            }
            return subject;
          });
          const updated = { ...section, subjects: updatedSubjects };
          if (selectedSection?.id === sectionId) {
            setSelectedSection(updated);
          }
          return updated;
        }
        if (section.subjects) {
          return { ...section, subjects: updateSections(section.subjects) };
        }
        return section;
      });
    };
    setSections(updateSections(sections));
  };

  // Add new top-level section
  const addNewSection = () => {
    const newSection = {
      id: Date.now() + Math.random(),
      level: 1,
      title: 'New Section',
      content: '',
      visible: true,
      subjects: []
    };
    setSections([...sections, newSection]);
    setSelectedSection(newSection);
  };

  // Add new subject to current section
  const addNewSubject = (sectionId) => {
    const newSubject = {
      id: Date.now() + Math.random(),
      level: 2,
      title: 'New Subsection',
      content: 'Add your content here...',
      visible: true,
      subjects: []
    };

    const updateSections = (sectionList) => {
      return sectionList.map(section => {
        if (section.id === sectionId) {
          const updated = {
            ...section,
            subjects: [...(section.subjects || []), newSubject]
          };
          setSelectedSection(updated);
          // Auto-expand the new subject
          setExpandedSubjects(prev => {
            const newSet = new Set(prev);
            newSet.add(newSubject.id);
            return newSet;
          });
          return updated;
        }
        if (section.subjects) {
          return { ...section, subjects: updateSections(section.subjects) };
        }
        return section;
      });
    };

    setSections(updateSections(sections));
  };

  // Delete subject
  const deleteSubject = (sectionId, subjectId) => {
    const updateSections = (sectionList) => {
      return sectionList.map(section => {
        if (section.id === sectionId) {
          const updatedSubjects = section.subjects.filter(s => s.id !== subjectId);
          const updated = { ...section, subjects: updatedSubjects };
          if (selectedSection?.id === sectionId) {
            setSelectedSection(updated);
          }
          return updated;
        }
        if (section.subjects) {
          return { ...section, subjects: updateSections(section.subjects) };
        }
        return section;
      });
    };
    setSections(updateSections(sections));
  };

  // Reconstruct prompt
  const reconstructPrompt = () => {
    let output = [];

    const processSection = (section, depth = 1) => {
      if (!section.visible) return;

      if (section.level === 2 && section.title.match(/^[a-zA-Z_][a-zA-Z0-9_]*$/)) {
        output.push(`<${section.title}>`);
        if (section.content) output.push(section.content);
        if (section.subjects && section.subjects.length > 0) {
          section.subjects.forEach(child => processSection(child, depth + 1));
        }
        output.push(`</${section.title}>`);
        output.push('');
      } else {
        const prefix = '#'.repeat(depth);
        output.push(`${prefix} ${section.title}`);
        if (section.content) {
          output.push('');
          output.push(section.content);
          output.push('');
        }
        if (section.subjects && section.subjects.length > 0) {
          section.subjects.forEach(child => processSection(child, depth + 1));
        }
      }
    };

    sections.forEach(section => processSection(section));
    return output.join('\n');
  };

