    const text = reconstructPrompt();
    const blob = new Blob([text], { type: 'text/markdown' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'organized-prompt.md';
    a.click();
    URL.revokeObjectURL(url);
  };

