              </div>

              {searchQuery && selectedSection?.subjects?.filter(s => filterContent(s.title) || filterContent(s.content)).length === 0 && (
                <div style={{
                  padding: '40px',
                  textAlign: 'center',
                  color: contentText
                }}>
                  <p style={{ margin: 0 }}>No results found for "{searchQuery}"</p>
                </div>
              )}
            </div>
          </div>
        </div>
      ) : (
        // Preview Mode - Full Width
        <div style={{
          flex: 1,
          display: 'flex',
          flexDirection: 'column',
          backgroundColor: contentBg
        }}>
          {/* Preview Header */}
          <div style={{
            padding: '24px 40px',
            borderBottom: `1px solid ${borderColor}`,
            backgroundColor: sidebarBg,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between'
          }}>
            <div>
              <h2 style={{
                fontSize: `${fontSize * 1.6}px`,
                fontWeight: '300',
                margin: '0 0 4px 0',
                color: headerText,
                letterSpacing: '-0.02em'
              }}>
                Live Preview
              </h2>
              <p style={{
                margin: 0,
                fontSize: `${fontSize * 0.9}px`,
                color: contentText
              }}>
                {sections.filter(s => s.visible).length} visible sections • Ready to copy or download
              </p>
            </div>
            <div style={{
              display: 'flex',
              gap: '12px'
            }}>
              <button
                onClick={copyToClipboard}
                style={{
                  padding: '10px 20px',
                  backgroundColor: accentColor,
                  color: '#FFFFFF',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  fontSize: `${fontSize}px`,
                  fontWeight: '500',
                  transition: prefersReducedMotion ? 'none' : 'opacity 200ms ease-out',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '8px'
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.opacity = '0.9';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.opacity = '1';
                }}
              >
                <span>📋</span> Copy to Clipboard
              </button>
              <button
                onClick={downloadPrompt}
                style={{
                  padding: '10px 20px',
                  backgroundColor: accentColor,
                  color: '#FFFFFF',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  fontSize: `${fontSize}px`,
                  fontWeight: '500',
                  transition: prefersReducedMotion ? 'none' : 'opacity 200ms ease-out',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '8px'
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.opacity = '0.9';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.opacity = '1';
                }}
              >
                <span>💾</span> Download
              </button>
            </div>
          </div>

          {/* Preview Content */}
          <div style={{
            flex: 1,
            overflowY: 'auto',
            padding: '40px',
            backgroundColor: sidebarBg
          }}>
            <div style={{
              maxWidth: '1200px',
              margin: '0 auto',
              backgroundColor: backgroundColor,
              borderRadius: '8px',
              border: `1px solid ${borderColor}`,
              padding: '32px',
              fontFamily: 'monospace',
              fontSize: `${fontSize * 0.95}px`,
              lineHeight: '1.6',
              color: contentText,
              whiteSpace: 'pre-wrap',
              wordBreak: 'break-word',
              boxShadow: '0 2px 8px rgba(0,0,0,0.04)'
            }}>
              {reconstructPrompt()}
            </div>
          </div>
        </div>
      )}
    </div>
  );

  return (
    <div className="prompt-organizer">
      {mainContent}
    </div>
  );
}

