/* Random Color Scheme Generator - Generates random harmonious color palettes */
const MANIFEST = {"type": "Tools.RandomColorSchemeGenerator", "description": "Generate random color schemes with instant randomization and copy functionality", "editorElement": {"selector": ".random-color-scheme", "displayName": "Random Color Scheme", "archetype": "container", "data": {"heading": {"dataType": "text", "displayName": "Heading", "defaultValue": "Random Color Scheme", "group": "Content"}}, "layout": {"resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical"}}};
function Component({ config = {} }) {
  const [colors, setColors] = React.useState(['#FF6B6B', '#4ECDC4', '#45B7D1', '#FFA07A', '#98D8C8']);
  const [copied, setCopied] = React.useState(null);
  const randomize = () => {const newColors = Array(5).fill(0).map(() => '#' + Math.floor(Math.random()*16777215).toString(16).padStart(6, '0')); setColors(newColors);};
  const copy = (color) => {if(navigator.clipboard){navigator.clipboard.writeText(color); setCopied(color); setTimeout(() => setCopied(null), 1500);}};
  return (<div style={{backgroundColor: '#FAFBFC', padding: '48px 24px', minHeight: '100vh'}}><div style={{maxWidth: '700px', margin: '0 auto'}}><h1 style={{fontSize: '32px', fontWeight: '600', textAlign: 'center', marginBottom: '32px'}}>Random Color Scheme Generator</h1><div style={{display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))', gap: '16px', marginBottom: '24px'}}>{colors.map((color, i) => (<div key={i} onClick={() => copy(color)} style={{aspectRatio: '1', backgroundColor: color, borderRadius: '8px', border: '1px solid #E5E7EB', cursor: 'pointer', display: 'flex', flexDirection: 'column', justifyContent: 'flex-end', padding: '16px', boxShadow: '0 2px 8px rgba(0,0,0,0.1)', transition: 'transform 200ms'}} onMouseEnter={(e) => e.currentTarget.style.transform = 'scale(1.05)'} onMouseLeave={(e) => e.currentTarget.style.transform = 'scale(1)'}><span style={{fontSize: '12px', fontFamily: 'monospace', fontWeight: '600', color: '#FFF', textShadow: '0 1px 2px rgba(0,0,0,0.5)'}}>{copied === color ? '✓ Copied!' : color}</span></div>))}</div><button onClick={randomize} style={{width: '100%', backgroundColor: '#3B82F6', color: '#FFF', border: 'none', borderRadius: '8px', padding: '14px', fontSize: '14px', fontWeight: '500', cursor: 'pointer', boxShadow: '0 2px 8px rgba(0,0,0,0.1)'}}>🎲 Generate New Scheme</button></div></div>);
}

