function Component({ config = {} }) {
  const heading = config?.heading || "Mockup Generator";
  const showHeading = config?.showHeading !== false;
  const defaultImageUrl = config?.defaultImageUrl || "https://images.unsplash.com/photo-1611162616305-c69b3037c2ba?w=400";
  const defaultDevice = config?.defaultDevice || "phone";
  const backgroundColor = config?.backgroundColor || "#F3F4F6";
  const cardBackground = config?.cardBackground || "#FFFFFF";
  const textColor = config?.textColor || "#1F2937";
  const labelColor = config?.labelColor || "#6B7280";
  const borderColor = config?.borderColor || "#E5E7EB";
  const accentColor = config?.accentColor || "#3B82F6";
  const deviceColor = config?.deviceColor || "#1F2937";
