      container: {maxWidth: '800px', aspectRatio: '16/10', padding: '8px 8px 24px', borderRadius: '12px'},
      screen: {borderRadius: '8px', paddingTop: '0'}
    }
  };

  const currentStyle = deviceStyles[device];

  return (
    <div style={{backgroundColor, padding: 'clamp(24px, 5vw, 48px)', fontFamily: 'system-ui, sans-serif', minHeight: '100vh'}}>
