        {showHeading && <h1 style={{fontSize: 'clamp(24px, 4vw, 32px)', fontWeight: '600', color: textColor, margin: '0 0 32px 0', textAlign: 'center'}}>{heading}</h1>}

        <div style={{backgroundColor: cardBackground, border: `1px solid ${borderColor}`, borderRadius: `${borderRadius}px`, padding: 'clamp(32px, 5vw, 64px)', marginBottom: '24px', boxShadow: '0 1px 2px rgba(0,0,0,0.05), 0 4px 12px rgba(0,0,0,0.03)', display: 'flex', justifyContent: 'center'}}>
          <div style={{...currentStyle.container, backgroundColor: deviceColor, boxShadow: '0 20px 60px rgba(0,0,0,0.3)', border: '4px solid #000', width: '100%', transition: 'all 400ms ease-out'}}>
            <div style={{...currentStyle.screen, backgroundColor: '#000', overflow: 'hidden', position: 'relative', height: '100%'}}>
              <img src={imageUrl} style={{width: '100%', height: '100%', objectFit: 'cover', display: 'block'}} alt="Mockup content" />
            </div>
          </div>
        </div>

        <div style={{backgroundColor: cardBackground, border: `1px solid ${borderColor}`, borderRadius: `${borderRadius}px`, padding: '24px', boxShadow: '0 1px 2px rgba(0,0,0,0.05)', marginBottom: '16px'}}>
          <div style={{display: 'flex', flexDirection: 'column', gap: '20px'}}>
            <div>
              <label style={{display: 'block', fontSize: '14px', fontWeight: '500', color: labelColor, marginBottom: '8px'}}>Device Type</label>
              <div style={{display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '8px'}}>
                {['phone', 'tablet', 'laptop'].map(d => (
                  <button key={d} onClick={() => setDevice(d)} style={{backgroundColor: device === d ? accentColor : 'transparent', color: device === d ? '#FFF' : textColor, border: `1px solid ${device === d ? accentColor : borderColor}`, borderRadius: `${borderRadius}px`, padding: '10px', fontSize: '13px', fontWeight: '500', cursor: 'pointer', textTransform: 'capitalize', transition: 'all 200ms'}}>{d}</button>
                ))}
              </div>
            </div>

            <div>
              <label style={{display: 'block', fontSize: '14px', fontWeight: '500', color: labelColor, marginBottom: '8px'}}>Image URL</label>
              <input type="text" value={imageUrl} onChange={(e) => setImageUrl(e.target.value)} placeholder="https://example.com/image.jpg" style={{width: '100%', backgroundColor: '#F9FAFB', border: `1px solid ${borderColor}`, borderRadius: `${borderRadius}px`, padding: '10px 12px', fontSize: '14px', color: textColor}} />
            </div>
          </div>
        </div>

        <label style={{display: 'block', width: '100%', backgroundColor: accentColor, color: '#FFF', border: 'none', borderRadius: `${borderRadius}px`, padding: '14px', fontSize: '14px', fontWeight: '500', cursor: 'pointer', textAlign: 'center', boxShadow: '0 2px 8px rgba(0,0,0,0.1)'}}>
          📷 Upload Image
          <input type="file" accept="image/*" onChange={handleFileUpload} style={{display: 'none'}} />
        </label>
      </div>
    </div>
  );
}

