      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const heading = config?.heading || "Photo Filter App";
  const showHeading = config?.showHeading !== false;
  const defaultImageUrl = config?.defaultImageUrl || "https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=1200";
  const backgroundColor = config?.backgroundColor || "#FAFBFC";
  const cardBackground = config?.cardBackground || "#FFFFFF";
  const textColor = config?.textColor || "#1F2937";
  const labelColor = config?.labelColor || "#6B7280";
  const borderColor = config?.borderColor || "#E5E7EB";
  const accentColor = config?.accentColor || "#3B82F6";
  const borderRadius = parseInt(config?.borderRadius || "8");
  const showPresets = config?.showPresets !== false;
  const showUpload = config?.showUpload !== false;
  const showDownload = config?.showDownload !== false;

  const [imageUrl, setImageUrl] = React.useState(defaultImageUrl);
  const [brightness, setBrightness] = React.useState(100);
  const [contrast, setContrast] = React.useState(100);
  const [saturate, setSaturate] = React.useState(100);
  const [grayscale, setGrayscale] = React.useState(0);
  const [sepia, setSepia] = React.useState(0);
  const [blur, setBlur] = React.useState(0);
  const [hueRotate, setHueRotate] = React.useState(0);

  const canvasRef = React.useRef(null);
  const imageRef = React.useRef(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const filterStyle = `brightness(${brightness}%) contrast(${contrast}%) saturate(${saturate}%) grayscale(${grayscale}%) sepia(${sepia}%) blur(${blur}px) hue-rotate(${hueRotate}deg)`;

  const presets = {
    normal: { brightness: 100, contrast: 100, saturate: 100, grayscale: 0, sepia: 0, blur: 0, hueRotate: 0 },
    vivid: { brightness: 110, contrast: 120, saturate: 140, grayscale: 0, sepia: 0, blur: 0, hueRotate: 0 },
    vintage: { brightness: 110, contrast: 90, saturate: 80, grayscale: 0, sepia: 40, blur: 0, hueRotate: 0 },
    blackWhite: { brightness: 100, contrast: 110, saturate: 0, grayscale: 100, sepia: 0, blur: 0, hueRotate: 0 },
    warm: { brightness: 105, contrast: 100, saturate: 120, grayscale: 0, sepia: 20, blur: 0, hueRotate: 10 },
    cool: { brightness: 100, contrast: 105, saturate: 110, grayscale: 0, sepia: 0, blur: 0, hueRotate: 200 },
    dreamy: { brightness: 115, contrast: 80, saturate: 90, grayscale: 0, sepia: 10, blur: 1, hueRotate: 0 }
  };

  const applyPreset = (preset) => {
    const values = presets[preset];
    setBrightness(values.brightness);
    setContrast(values.contrast);
    setSaturate(values.saturate);
    setGrayscale(values.grayscale);
    setSepia(values.sepia);
    setBlur(values.blur);
    setHueRotate(values.hueRotate);
  };

  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setImageUrl(event.target.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const downloadImage = () => {
    const canvas = canvasRef.current;
    const image = imageRef.current;

    if (!canvas || !image) return;

    const ctx = canvas.getContext('2d');
    canvas.width = image.naturalWidth;
    canvas.height = image.naturalHeight;

    ctx.filter = filterStyle;
    ctx.drawImage(image, 0, 0);

    const link = document.createElement('a');
    link.download = 'filtered-photo.png';
    link.href = canvas.toDataURL();
    link.click();

    ctx.filter = 'none';
  };

  return (
    <div
      className="photo-filter-app"
      style={{
        backgroundColor: backgroundColor,
        padding: 'clamp(24px, 5vw, 48px)',
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
        minHeight: '100vh'
      }}
    >
      <div
        style={{
          maxWidth: '1200px',
          margin: '0 auto'
        }}
      >
        {showHeading && (
          <h1
            style={{
              fontSize: 'clamp(24px, 4vw, 32px)',
              fontWeight: '600',
              color: textColor,
              margin: '0 0 32px 0',
              textAlign: 'center'
            }}
          >
            {heading}
          </h1>
        )}

        <div
          style={{
            display: 'grid',
            gridTemplateColumns: '1fr',
            gap: '24px'
          }}
        >
          {/* Image Preview */}
          <div
            style={{
              backgroundColor: cardBackground,
              border: `1px solid ${borderColor}`,
              borderRadius: `${borderRadius}px`,
              padding: '24px',
              boxShadow: '0 1px 2px rgba(0,0,0,0.05), 0 4px 12px rgba(0,0,0,0.03)'
            }}
          >
            <img
              ref={imageRef}
              src={imageUrl}
              alt="Photo to filter"
              style={{
                width: '100%',
                height: 'auto',
                borderRadius: `${borderRadius}px`,
                filter: filterStyle,
                transition: prefersReducedMotion ? 'none' : 'filter 200ms ease-out'
              }}
              crossOrigin="anonymous"
            />
            <canvas ref={canvasRef} style={{ display: 'none' }} />
          </div>

          {/* Preset Filters */}
          {showPresets && (
            <div
              style={{
                backgroundColor: cardBackground,
                border: `1px solid ${borderColor}`,
                borderRadius: `${borderRadius}px`,
                padding: '20px',
                boxShadow: '0 1px 2px rgba(0,0,0,0.05), 0 4px 12px rgba(0,0,0,0.03)'
              }}
            >
              <h3
                style={{
                  fontSize: '16px',
                  fontWeight: '600',
                  color: textColor,
                  margin: '0 0 16px 0'
                }}
              >
                Preset Filters
              </h3>
              <div
                style={{
                  display: 'grid',
                  gridTemplateColumns: 'repeat(auto-fit, minmax(100px, 1fr))',
                  gap: '8px'
                }}
              >
                {Object.keys(presets).map((preset) => (
                  <button
                    key={preset}
                    onClick={() => applyPreset(preset)}
                    style={{
                      backgroundColor: 'transparent',
                      border: `1px solid ${borderColor}`,
                      borderRadius: `${borderRadius}px`,
                      padding: '10px 12px',
                      fontSize: '13px',
                      fontWeight: '500',
                      color: textColor,
                      cursor: 'pointer',
                      textTransform: 'capitalize',
                      transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out'
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.backgroundColor = '#F3F4F6';
                      e.currentTarget.style.borderColor = accentColor;
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.backgroundColor = 'transparent';
                      e.currentTarget.style.borderColor = borderColor;
                    }}
                  >
                    {preset}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Filter Controls */}
          <div
            style={{
              backgroundColor: cardBackground,
              border: `1px solid ${borderColor}`,
              borderRadius: `${borderRadius}px`,
              padding: '24px',
              boxShadow: '0 1px 2px rgba(0,0,0,0.05), 0 4px 12px rgba(0,0,0,0.03)'
            }}
          >
            <h3
              style={{
                fontSize: '16px',
                fontWeight: '600',
                color: textColor,
                margin: '0 0 20px 0'
              }}
            >
              Adjust Filters
            </h3>
            <div
              style={{
                display: 'grid',
                gridTemplateColumns: '1fr 1fr',
                gap: '20px'
              }}
            >
              {[
                { label: 'Brightness', value: brightness, setter: setBrightness, min: 0, max: 200, unit: '%' },
                { label: 'Contrast', value: contrast, setter: setContrast, min: 0, max: 200, unit: '%' },
                { label: 'Saturation', value: saturate, setter: setSaturate, min: 0, max: 200, unit: '%' },
                { label: 'Grayscale', value: grayscale, setter: setGrayscale, min: 0, max: 100, unit: '%' },
                { label: 'Sepia', value: sepia, setter: setSepia, min: 0, max: 100, unit: '%' },
                { label: 'Blur', value: blur, setter: setBlur, min: 0, max: 10, unit: 'px' },
                { label: 'Hue Rotate', value: hueRotate, setter: setHueRotate, min: 0, max: 360, unit: '°' }
              ].map(({ label, value, setter, min, max, unit }) => (
                <div key={label}>
                  <label
                    style={{
                      display: 'block',
                      fontSize: '14px',
                      fontWeight: '500',
                      color: labelColor,
                      marginBottom: '8px'
                    }}
                  >
                    {label}: {value}{unit}
                  </label>
                  <input
                    type="range"
                    min={min}
                    max={max}
                    value={value}
                    onChange={(e) => setter(parseInt(e.target.value))}
                    style={{
                      width: '100%',
                      height: '6px',
                      borderRadius: '3px',
                      cursor: 'pointer',
                      accentColor: accentColor
                    }}
                  />
                </div>
              ))}
            </div>
          </div>

          {/* Action Buttons */}
          <div
            style={{
              display: 'flex',
              gap: '12px',
              flexWrap: 'wrap'
            }}
          >
            {showUpload && (
              <label
                style={{
                  flex: 1,
                  minWidth: '150px',
                  backgroundColor: 'transparent',
                  color: textColor,
                  border: `1px solid ${borderColor}`,
                  borderRadius: `${borderRadius}px`,
                  padding: '12px 20px',
                  fontSize: '14px',
                  fontWeight: '500',
                  cursor: 'pointer',
                  textAlign: 'center',
                  transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out'
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.backgroundColor = '#F3F4F6';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.backgroundColor = 'transparent';
                }}
              >
                📷 Upload Photo
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFileUpload}
                  style={{ display: 'none' }}
                />
              </label>
            )}

            {showDownload && (
              <button
                onClick={downloadImage}
                style={{
                  flex: 1,
                  minWidth: '150px',
                  backgroundColor: accentColor,
                  color: '#FFFFFF',
                  border: 'none',
                  borderRadius: `${borderRadius}px`,
                  padding: '12px 20px',
                  fontSize: '14px',
                  fontWeight: '500',
                  cursor: 'pointer',
                  transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out',
                  boxShadow: '0 2px 8px rgba(0,0,0,0.1)'
                }}
                onMouseEnter={(e) => {
                  if (!prefersReducedMotion) {
                    e.currentTarget.style.transform = 'scale(0.98)';
                  }
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.transform = 'scale(1)';
                }}
              >
                ⬇ Download Filtered Photo
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
